      SUBROUTINE MR2RCCC     MULTIPLIES RC2 AND RC AND STORES RESULT IN RCCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'RC.CIN'      INCLUDE 'RCP.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'RS.CIN'      INCLUDE 'TC.CIN'      INCLUDE 'TC2.CIN'      INCLUDE 'TS.CIN'      INCLUDE 'UC.CIN'      INCLUDE 'UC2.CIN'      INCLUDE 'US.CIN'CC---------------------------------------------------------------------      IF (RCP) GO TO 50      DO 10 JK = 1, 36   10 RSL(JK) = RC2L(JK)      IF (NORD2 .GE. 2) THEN        DO 20 JKM = 1, 105   20   TSL(JKM) = TC2L(JKM)      ENDIF      IF (NORD2 .GE. 3) THEN        DO 30 JKLM = 1, 280   30   USL(JKLM) = UC2L(JKLM)      ENDIF      GO TO 100C   50 IF (NORD2 .EQ. 1) THEN        CALL CAB(RS,RC2,RC)      ELSE IF (NORD2 .EQ. 2) THEN        CALL CAB2(RS,TS,RC2,TC2,RC,TC)      ELSE IF (NORD2 .EQ. 3) THEN        CALL CAB3(RS,TS,US,RC2,TC2,UC2,RC,TC,UC)      ENDIFC  100 RETURN      END